quickstart.js:
const table = new TinyDataTable("#users-table", {
  ajax: "/api/users",
  sortable: true,
  searchable: true,
  paginated: true
});

new TinyScheduler("#scheduler", {
  view: "week",
  resources: true,
  events: myEvents
});

new TinyAutocomplete("#city-search", {
  source: q => fetch(`/api/cities?q=${q}`).then(r => r.json()),
  minChars: 2
});

new TinySelectize("#team-select", {
  multiple: true,
  searchable: true,
  options: teams
});

new TinyChips("#topics", {
  separator: ",",
  autocomplete: ["UI", "JavaScript", "Design"]
});

new TinyDatePicker("#start-date", {
  mode: "range",
  theme: "dark"
});

new tinyColorPicker("#theme-color", {
  theme: "dark",
  cssVar: "--brand-color"
});

const signature = new TinySignature("#signature-pad", {
  width: 540,
  height: 240
});

new TinyTabs("#account-tabs", {
  tabs: ["Overview", "Members", "Billing"]
});

new TinyDropdown("#actions-btn", {
  items: [{ label: "Edit" }, { label: "Archive" }]
});

new TinySideNav("#main-sidenav", {
  position: "left",
  lockScroll: true
});

new TinyCollapsible("#faq-list", {
  accordion: true,
  duration: 220
});

new TinyGroupButton("#view-switch", {
  multiple: false,
  options: ["Day", "Week", "Month"]
});

new TinyGallery("#portfolio-gallery", {
  reorderable: true,
  lightbox: true
});

new TinyLightbox(".gallery", {
  captions: true,
  zoom: true
});

new TinyCarousel("#hero-carousel", {
  autoplay: false,
  visibleSlides: 1
});

document.querySelector("#delete-btn").addEventListener("click", () => {
  TinySwal.fire({ title: "Delete item?", confirmButtonText: "Confirm" });
});

new TinyInlineEditor("#article-intro", {
  toolbar: true,
  autosave: true
});

new TinySortableList("#task-order", {
  handle: null,
  keyboard: true
});
